// Authored follow-up explanations. Each branch attaches to a statement, and a
// child branch returns to that exact statement rather than a generic topic list.
const p = text => `<p>${text}</p>`;
const eq = text => `<div class="text-equation">${text}</div>`;
const s = (title, ...body) => ({ title, body: body.join('\n') });
const b = (slug, title, question, parent, after, sections) => ({ slug, title, question, parent, after, sections });

export const tutorials = {
  'pv-work': [
    b('boundary-force', 'Why does external pressure determine work?', 'Which force actually crosses the boundary?', 'index', 0, [
      s('Choose a boundary and a sign', p('Take the gas as the system and let x increase when its piston moves outward. The external load exerts an inward force on that boundary. With a frictionless piston whose kinetic-energy change is negligible, the energy delivered to the gas as work is the load force dotted with the displacement.'), eq('δw = (−P<sub>ext</sub>A) dx = −P<sub>ext</sub> dV'), p('The symbol δ marks a path-dependent energy transfer. There is no state variable w whose endpoint difference gives every possible work transfer. The piston assumptions matter: a piston gaining kinetic energy can temporarily store energy that has not gone into the external load.')),
      s('Why not just use the gas pressure?', p('A gas can expand into vacuum while maintaining a nonzero pressure internally. The load then receives no mechanical energy because P<sub>ext</sub> = 0. Substituting gas pressure would predict work that was never delivered. During a rapid process the gas may not even have a single uniform pressure.'), p('For slow, mechanically reversible motion, the two pressures approach equality. Only in that limit may the equilibrium equation of state supply P in the work integral.')),
      s('A finite-load calculation', eq('P<sub>ext</sub> = 100 kPa,  ΔV = 2.0 L\nw = −(100 kPa)(2.0 L) = −200 J'), p('The conversion follows directly from 1 kPa·L = 1 J. Compression reverses the sign because ΔV becomes negative. No ideal-gas assumption entered the calculation.'))
    ]),
    b('path-dependence', 'Why is work a path quantity?', 'Can the same endpoints give different work?', 'index', 2, [
      s('Use identical ideal-gas endpoints', p('Let a fixed amount of ideal gas begin at T and V₁ and finish at the same T and V₂ = 2V₁. One possible route is a reversible isothermal expansion maintained by a heat bath. Another is insulated free expansion into vacuum, followed by equilibration.'), eq('w<sub>rev</sub> = −nRT ln 2\nw<sub>free</sub> = 0'), p('For the free expansion of an ideal gas, ΔU = 0 implies the final temperature is unchanged. Both routes therefore connect the specified states, but exchange different amounts of work.')),
      s('Energy conservation still holds', eq('ΔU = q + w = 0\nq<sub>rev</sub> = nRT ln 2,  q<sub>free</sub> = 0'), p('The state function is internal energy. Heat and work can trade off while their sum remains fixed by the endpoints. On a quasistatic pressure–volume diagram, −w is the signed area under the path; endpoint coordinates do not specify that area.')),
      s('A cycle exposes the distinction', p('Return to the initial state along a different route. Every state function has zero net change over the cycle. Work need not vanish, because the forward and return paths can enclose an area. The cycle then exchanges an equal and opposite net amount of heat.'))
    ]),
    b('reversible-limit', 'What does the reversible limit mean mechanically?', 'How can a piston move if the pressures are equal?', 'boundary-force', 1, [
      s('Keep an infinitesimal imbalance', p('For expansion, choose P<sub>ext</sub> = P − ε with ε positive and arbitrarily small, and remove tiny weights as the gas expands. A literal exact balance would produce no acceleration from rest. Reversibility describes the limiting sequence of states as the required imbalance tends to zero.'), eq('δw = −(P − ε) dV  →  −P dV as ε → 0')),
      s('Slow is necessary but not sufficient', p('A piston sliding slowly with friction still dissipates energy. Reversing its motion requires overcoming friction in the opposite direction, so the original path is not recovered by an infinitesimal change of load. A reversible model also excludes friction and finite temperature gradients during heat exchange.')),
      s('Why this limit gives the largest output', p('Along an isothermal ideal-gas expansion, a load greater than the gas pressure would stop outward motion. A smaller load receives less work per volume increment. A load infinitesimally below the gas pressure therefore gives the largest work output among these expansion paths.'), eq('work output = −w;  w<sub>rev</sub> is most negative'), p('This statement compares expansion between the specified endpoints with the specified thermal constraints; it is not a rule for unrelated paths.'))
    ])
  ],
  enthalpy: [
    b('energy-accounting', 'What does enthalpy add to internal energy?', 'Why introduce U + PV?', 'index', 1, [
      s('Make room in the surroundings', p('An expanding closed system must displace its surroundings. At a fixed imposed pressure P, creating an extra volume ΔV transfers PΔV of energy outward as mechanical work. Heat supplied to the system must cover both this transfer and the internal-energy increase.'), eq('q = ΔU + PΔV')),
      s('Package the pressure constraint into a state function', p('Define H = U + PV. At constant pressure, its finite change is exactly the combination in the heat balance. H remains defined for every equilibrium state, whether or not the actual experiment holds pressure constant.'), eq('dH = dU + P dV + V dP\ndH = δq + V dP  (reversible PV work only)'), p('Enthalpy is not heat stored inside matter. Heat describes energy crossing a boundary; enthalpy assigns a value to an equilibrium state. Their changes coincide only for specified constraints.')),
      s('Closed-system heat versus flow energy', p('The PV term also appears in a steady-flow apparatus because a stream must be pushed into or out of a control volume. That is a separate energy balance. The present proof concerns a closed system, so no mass carries energy across its boundary.'), p('For a constant-pressure process absorbing 50 J while doing 20 J of expansion work, ΔU = 30 J and ΔH = 50 J.'))
    ]),
    b('irreversible-heat', 'Does q at constant pressure require reversibility?', 'Can an irreversible reaction still have qₚ = ΔH?', 'index', 2, [
      s('Use a finite balance rather than a reversible differential', p('Assume a closed system expands against a constant P<sub>ext</sub>, only PV work occurs, piston energy storage is negligible, and initial and final system pressures equal P<sub>ext</sub>. The intermediate states may be irreversible.'), eq('ΔU = q − P<sub>ext</sub>(V₂ − V₁)\nΔH = ΔU + (P₂V₂ − P₁V₁)\nP₁ = P₂ = P<sub>ext</sub>  ⇒  ΔH = q')),
      s('The endpoint condition does real work', p('During a rapid reaction the gas need not possess a uniform equilibrium pressure. We do not insert such an intermediate pressure into the work integral. The constant external load determines the work; the equilibrium endpoints determine Δ(PV). Their pressure values match in the stated experiment.')),
      s('What changes with electrical work?', eq('ΔU = q − PΔV + w<sub>non-PV,on</sub>\nΔH = q + w<sub>non-PV,on</sub>'), p('A cell delivering electrical work has w<sub>non-PV,on</sub> negative. Its heat transfer is therefore not determined by ΔH alone. Constant pressure by itself is insufficient; the work terms must also be specified.'))
    ]),
    b('legendre-transform', 'Why is enthalpy natural at fixed pressure?', 'Is H = U + PV just a convenient trick?', 'energy-accounting', 1, [
      s('Start with the fundamental thermodynamic relation', p('For a simple compressible system of fixed composition, the equilibrium differential of internal energy is dU = T dS − P dV. This combines the reversible definitions of temperature and pressure with the first law.'), eq('dH = d(U + PV) = T dS + V dP')),
      s('Exchange a natural variable', p('U is naturally expressed as U(S,V); its V derivative is −P. Adding PV cancels the dV term and replaces volume with pressure as an independent variable. This operation is a Legendre transform, familiar from switching variables in analytical mechanics.'), eq('T = (∂H/∂S)<sub>P</sub>,  V = (∂H/∂P)<sub>S</sub>'), p('The transform does not add an energy source. It changes which controlled variables appear directly in the differential.')),
      s('Connect to heat capacity', p('At fixed P and fixed composition, the heat needed for an infinitesimal reversible temperature increase is dH. Consequently Cₚ = (∂H/∂T)<sub>P</sub>. By contrast, holding V fixed makes dU the corresponding heat, giving Cᵥ = (∂U/∂T)<sub>V</sub>.'), p('Neither derivative requires heat capacity to be independent of temperature.'))
    ])
  ],
  'cp-cv': [
    b('ideal-internal-energy', 'Why does an ideal gas have U = U(T)?', 'Can PV = nRT justify this extra premise?', 'index', 0, [
      s('Begin with equilibrium thermodynamics', p('At fixed amount and composition, regard U as a function of T and V. The fundamental relation and a Maxwell relation imply an identity that is valid for any simple compressible fluid.'), eq('(∂U/∂V)<sub>T</sub> = T(∂P/∂T)<sub>V</sub> − P'), p('This is stronger than an algebraic rearrangement of PV = nRT: it uses the thermodynamic structure of U and S as state functions.')),
      s('Insert the ideal equation of state', eq('P = nRT/V\nT(∂P/∂T)<sub>V</sub> − P = T(nR/V) − nRT/V = 0'), p('Thus changing V at fixed T does not change U. Within a connected single-phase ideal-gas region, U depends only on T for the fixed sample. Rotational and vibrational energies can change the shape of U(T); they do not invalidate this conclusion for a fixed-composition ideal gas.')),
      s('A microscopic interpretation', p('If intermolecular interaction energy is negligible, moving molecules farther apart does not change their potential energy. Equilibrium translational and internal molecular energies are set by temperature. A real gas can have an interaction-energy contribution depending on density, so its internal energy need not have the same property.'))
    ]),
    b('general-capacity-gap', 'What replaces Cₚ − Cᵥ = nR for a real fluid?', 'How special is the ideal-gas result?', 'index', 2, [
      s('Compare two entropy derivatives', p('For a fixed sample, Cₚ = T(∂S/∂T)<sub>P</sub> and Cᵥ = T(∂S/∂T)<sub>V</sub>. Apply the chain rule to S(T,V) along a constant-pressure path, then use (∂S/∂V)<sub>T</sub> = (∂P/∂T)<sub>V</sub>.'), eq('Cₚ − Cᵥ = T(∂P/∂T)<sub>V</sub>(∂V/∂T)<sub>P</sub>')),
      s('Express it using measurable responses', p('Define the thermal expansion coefficient α = (1/V)(∂V/∂T)<sub>P</sub> and the isothermal compressibility κ<sub>T</sub> = −(1/V)(∂V/∂P)<sub>T</sub>. Setting dV = 0 in the equation for V(T,P) gives (∂P/∂T)<sub>V</sub> = α/κ<sub>T</sub>.'), eq('Cₚ − Cᵥ = TVα²/κ<sub>T</sub>'), p('For a mechanically stable phase κ<sub>T</sub> is positive, so Cₚ ≥ Cᵥ. The dimensions are K·m³·K⁻²·Pa = J K⁻¹.')),
      s('Recover the ideal limit', eq('ideal gas: α = 1/T,  κ<sub>T</sub> = 1/P\nTVα²/κ<sub>T</sub> = PV/T = nR'), p('The difference is therefore independent of the number of active internal molecular modes. Both heat capacities may vary with T while their ideal-gas difference remains nR.'))
    ]),
    b('maxwell-identity', 'Derive the internal-energy volume identity', 'Where did that derivative identity come from?', 'ideal-internal-energy', 0, [
      s('Use the Helmholtz free energy', p('Define A = U − TS for a fixed-composition simple compressible equilibrium system. Then dA = −S dT − P dV. Equality of mixed partial derivatives of the smooth state function A(T,V) gives a Maxwell relation.'), eq('(∂S/∂V)<sub>T</sub> = (∂P/∂T)<sub>V</sub>')),
      s('Differentiate U while holding T fixed', p('Along a constant-temperature variation, the fundamental relation dU = T dS − P dV has coefficient T(∂S/∂V)<sub>T</sub> − P in front of dV. Substitution proves the identity.'), eq('(∂U/∂V)<sub>T</sub> = T(∂S/∂V)<sub>T</sub> − P\n= T(∂P/∂T)<sub>V</sub> − P')),
      s('Test a nonideal model', p('For the molar van der Waals equation P = RT/(v − b) − a/v² with constant a and b, the identity gives (∂u/∂v)<sub>T</sub> = a/v². Integration at fixed T yields u(T,v) = f(T) − a/v. Expansion reduces the magnitude of the attractive potential energy and raises u at fixed T.'), p('The ideal-gas limit a = b = 0 returns zero volume dependence. This is a consistency calculation within that equation-of-state model.'))
    ])
  ],
  'isothermal-work': [
    b('isothermal-energy', 'How can temperature stay fixed while work leaves?', 'Where does the expansion energy come from?', 'index', 3, [
      s('Internal energy and heat are different concepts', p('For a fixed-composition ideal gas, U depends only on T. An isothermal process therefore has ΔU = 0, even though substantial heat and work can cross the boundary. Energy conservation constrains their sum.'), eq('0 = ΔU = q + w\nq<sub>rev</sub> = nRT ln(V₂/V₁)')),
      s('The thermal reservoir supplies the work output', p('During a reversible expansion the moving piston removes energy. Heat from a reservoir at an infinitesimally higher temperature restores that energy without a finite temperature change of the gas. Strict reversibility is a limit in which the temperature difference and pressure imbalance both tend to zero.'), p('Isothermal does not mean insulated. Insulation imposes q = 0; a reversible insulated expansion of an ideal gas normally cools it.')),
      s('An explicit comparison', eq('1.00 mol, 300 K, V₂/V₁ = 2\nw<sub>rev</sub> = −1.729 kJ,  q<sub>rev</sub> = +1.729 kJ'), p('An insulated free expansion between the same ideal-gas endpoints has q = w = 0. Equal endpoint temperatures do not determine either transfer separately.'))
    ]),
    b('logarithm-and-bounds', 'Why a logarithm, and why the reversible value?', 'What does the pressure–volume area tell us?', 'index', 2, [
      s('Equal ratios give equal contributions', p('On this ideal-gas isotherm, P = nRT/V. Integrating pressure over a small volume interval gives nRT dV/V. The fractional volume change matters: expansion from V to 2V gives the same work as expansion from 2V to 4V.'), eq('∫<sub>V₁</sub><sup>V₂</sup> dV/V = ln(V₂/V₁)'), p('Writing ln V alone is shorthand for an antiderivative with a reference volume. The definite logarithmic ratio is dimensionless and independent of the chosen volume unit.')),
      s('Compare with one constant external load', p('Choose P<sub>ext</sub> = nRT/V₂ and let the gas equilibrate against that load while a bath maintains the endpoint temperature. The constant-load expansion delivers less work than the reversible path.'), eq('−w<sub>load</sub> = nRT(1 − V₁/V₂)\n−w<sub>rev</sub> = nRT ln(V₂/V₁)'), p('For doubling, the coefficients are 0.500 and 0.693. A finite pressure imbalance gives less output.')),
      s('Compression has the corresponding cost', p('A finite pressure excess is needed to drive irreversible compression. With the same thermal constraints, reversible compression requires the least work input. Always state whether work is being counted on the system or delivered by it before comparing signs.'))
    ]),
    b('adiabatic-comparison', 'What if the gas is insulated instead?', 'Why does a reversible adiabatic expansion cool?', 'isothermal-energy', 1, [
      s('Combine the first law with q = 0', p('Assume fixed amount and composition, an ideal gas, reversible PV work, and a temperature-independent sample Cᵥ. Then dU = Cᵥ dT and the first law becomes:'), eq('Cᵥ dT = −P dV = −nRT dV/V')),
      s('Integrate the separated variables', eq('dT/T = −(nR/Cᵥ) dV/V\nT₂/T₁ = (V₁/V₂)<sup>nR/Cᵥ</sup>'), p('Let γ = Cₚ/Cᵥ. Since Cₚ − Cᵥ = nR, the exponent nR/Cᵥ equals γ − 1. Combining this result with PV = nRT gives PV<sup>γ</sup> = constant along the reversible adiabat.')),
      s('Check the sign and assumptions', p('Expansion makes V₂ &gt; V₁, so T₂ &lt; T₁. Work comes from internal energy because no heat enters. With variable Cᵥ, retain ∫ Cᵥ(T)dT/T rather than using a constant γ.'), p('Insulation alone does not establish PV<sup>γ</sup> = constant. An insulated free expansion is irreversible, does zero PV work, and leaves an ideal gas at unchanged temperature.'))
    ])
  ],
  'gas-entropy': [
    b('entropy-state-function', 'Why can an imagined reversible path give the answer?', 'The actual expansion is irreversible—what now?', 'index', 0, [
      s('Distinguish the definition from actual heat', p('Entropy is a state function defined between equilibrium states by integrating δq<sub>rev</sub>/T on a reversible calculation path. The actual process need not follow that path. This is analogous to evaluating a conservative potential difference along a mathematically convenient route.'), eq('S₂ − S₁ = ∫<sub>1→2, rev</sub> δq/T')),
      s('Account for entropy production', p('For a closed system exchanging heat with a boundary temperature T<sub>b</sub>, entropy accounting separates transfer from generation. With multiple contacts, sum the transfer terms.'), eq('ΔS = ∫ δq<sub>actual</sub>/T<sub>b</sub> + S<sub>gen</sub>\nS<sub>gen</sub> ≥ 0'), p('Insulation removes the transfer term; it does not require S<sub>gen</sub> = 0. Free expansion is a direct example.')),
      s('Choose two easy reversible legs', p('To connect (T₁,V₁) to (T₂,V₂), first heat reversibly at fixed V₁, then expand reversibly at fixed T₂. The first leg gives n∫Cᵥ,ₘ(T)dT/T and the second gives nR ln(V₂/V₁). Their sum equals the entropy change for every path with those endpoints.'))
    ]),
    b('variable-heat-capacity', 'What if heat capacity is not constant?', 'Which part of the logarithmic formula is approximate?', 'index', 2, [
      s('Keep the temperature integral', eq('ΔS = n∫<sub>T₁</sub><sup>T₂</sup> Cᵥ,ₘ(T) dT/T + nR ln(V₂/V₁)'), p('The volume term remains logarithmic for an ideal gas of fixed composition. Only the temperature integral required constant Cᵥ,ₘ in the short formula. Molecular vibrational excitation can make that assumption inaccurate over a large interval.')),
      s('Integrate a simple temperature-dependent model', p('Suppose Cᵥ,ₘ(T) = a + bT over the relevant range, where a has units J mol⁻¹ K⁻¹ and b has units J mol⁻¹ K⁻². Then:'), eq('ΔS = n[a ln(T₂/T₁) + b(T₂ − T₁)]\n+ nR ln(V₂/V₁)'), p('Every term has units J K⁻¹. The expression reduces continuously to the constant-heat-capacity formula as b tends to zero.')),
      s('An alternative using pressure', p('Use V₂/V₁ = (T₂/T₁)(P₁/P₂) and Cₚ,ₘ(T) = Cᵥ,ₘ(T) + R. The same endpoint entropy change can be written:'), eq('ΔS = n∫<sub>T₁</sub><sup>T₂</sup> Cₚ,ₘ(T) dT/T − nR ln(P₂/P₁)'), p('These equivalent forms are a useful check on both algebra and sign.'))
    ]),
    b('counting-volume', 'Can state counting explain the volume term?', 'Why does more room mean nR ln(V₂/V₁)?', 'entropy-state-function', 2, [
      s('Count accessible positions', p('For N noninteracting classical particles at fixed total energy, each particle position can range over volume V. The position part of the phase-space volume is therefore proportional to V<sup>N</sup>. Momentum factors are unchanged when comparing equal-energy ideal-gas states.'), eq('Ω₂/Ω₁ = (V₂/V₁)<sup>N</sup>')),
      s('Apply Boltzmann entropy', eq('ΔS = k<sub>B</sub> ln(Ω₂/Ω₁)\n= Nk<sub>B</sub> ln(V₂/V₁) = nR ln(V₂/V₁)'), p('The phase-space normalization, the indistinguishability factor N!, and the momentum contribution cancel in this fixed-N ratio. This calculation explains the isothermal volume term; it is not a derivation of the full temperature term for every type of molecule.')),
      s('Why free expansion increases entropy', p('Removing a partition opens additional accessible positions without changing ideal-gas internal energy. The equilibrium macrostate occupies vastly more microstates. There is no contradiction with energy conservation: energy constrains which states are accessible, while entropy measures their statistical multiplicity.'), p('For 1.00 mol doubling its volume, the change is R ln 2 = 5.76 J K⁻¹ whether the expansion is reversible or free.'))
    ])
  ],
  gibbs: [
    b('reservoir-entropy', 'Why is surroundings entropy −q/T?', 'May we use q/T for an irreversible process?', 'index', 0, [
      s('Model the surroundings as a reservoir', p('An ideal thermal reservoir is so large that absorbing a finite amount of energy does not appreciably change its temperature. It remains arbitrarily close to equilibrium, so its entropy change can be evaluated from its own equilibrium states.'), eq('dS<sub>res</sub> = dU<sub>res</sub>/T\nΔS<sub>res</sub> = q<sub>res</sub>/T = −q<sub>sys</sub>/T'), p('The reservoir is taken to exchange heat only in this balance. A separate mechanical pressure reservoir receives PV work without an entropy-transfer term.')),
      s('The irreversible system is a separate issue', p('A rapidly reacting system can generate entropy internally, so its entropy change is generally not q<sub>sys</sub>/T. The reservoir formula does not impose reversibility on that system. When the surroundings consist only of the ideal heat and pressure reservoirs, their contributions are fully accounted for in the Gibbs argument.')),
      s('A finite bath changes the calculation', p('If a bath with constant heat capacity C cools from T₁ to T₂, its entropy change is C ln(T₂/T₁), while its heat change is C(T₂ − T₁). Dividing by one arbitrarily selected temperature would be wrong. The compact ΔG = −TΔS<sub>univ</sub> proof requires a fixed common reservoir temperature.'))
    ]),
    b('gibbs-work', 'How is Gibbs energy related to useful work?', 'What changes if the system delivers electricity?', 'index', 3, [
      s('Retain the non-PV work term', p('At fixed T and P with a closed system and a thermal reservoir at T, let w<sub>non-PV,on</sub> denote work on the system other than PV work. The first law gives q = ΔH − w<sub>non-PV,on</sub>.'), eq('ΔS<sub>univ</sub> = ΔS − (ΔH − w<sub>non-PV,on</sub>)/T\nΔG = w<sub>non-PV,on</sub> − TΔS<sub>univ</sub>')),
      s('Read the work bound with the sign convention', eq('w<sub>non-PV,out</sub> = −w<sub>non-PV,on</sub> ≤ −ΔG'), p('A spontaneous decrease in Gibbs energy sets the maximum non-PV work output. Equality requires zero entropy generation, the reversible limit. This is the origin of the relation ΔᵣG = −nFE for a reversible electrochemical cell.')),
      s('Spontaneity does not predict speed', p('A negative Gibbs driving force indicates which direction is thermodynamically allowed under the constraints. It does not remove an activation barrier. A metastable mixture can persist for a long time despite a lower-G state being available.'), p('For a reacting mixture, the local criterion uses ΔᵣG = (∂G/∂ξ)<sub>T,P</sub>. The total finite ΔG is an integral of that changing derivative.'))
    ]),
    b('gibbs-minimum', 'Why does equilibrium minimize G?', 'Is ΔG = 0 sufficient to prove stability?', 'reservoir-entropy', 1, [
      s('Hold the environmental constraints fixed', p('Consider an infinitesimal change in a closed system coupled to fixed T and P reservoirs, with no imposed non-PV work. The second law gives dG = −T dS<sub>univ</sub> ≤ 0. The system can relax only toward accessible states of lower G.')),
      s('Separate stationarity from stability', eq('dG = (∂G/∂ξ)<sub>T,P</sub> dξ = ΔᵣG dξ\ninterior equilibrium: ΔᵣG = 0\nlocal stability: (∂²G/∂ξ²)<sub>T,P</sub> &gt; 0'), p('At an interior composition both signs of a sufficiently small reaction extent are allowed. A nonzero first derivative would permit a decrease in G in one direction. A zero derivative can also describe a maximum, so curvature matters.')),
      s('Respect the feasible composition range', p('At a boundary where a species is absent, one direction of reaction may be impossible. The minimum must then be tested with the allowed variations rather than assuming an interior stationary point. Multiple reactions require a minimum with respect to every independent feasible extent.'), p('A global equilibrium is the lowest accessible G under the conservation constraints. A local minimum separated by a barrier can instead be metastable.'))
    ])
  ],
  'reaction-gibbs': [
    b('chemical-potential', 'What is chemical potential, and why a logarithm?', 'Where does μ = μ° + RT ln a come from?', 'index', 1, [
      s('An energy cost per added mole', p('Chemical potential is the partial molar Gibbs energy: μᵢ = (∂G/∂nᵢ)<sub>T,P,nⱼ</sub>. It measures how G changes when a little of species i is added while the other amounts, temperature, and pressure are held fixed. The mixture volume can change in this definition.')),
      s('Derive the pressure dependence for an ideal gas', p('For a pure fluid, dμ = −sₘ dT + vₘ dP. On an ideal-gas isotherm vₘ = RT/P. Integrate from a standard pressure p° to P:'), eq('μ(T,P) − μ°(T) = ∫<sub>p°</sub><sup>P</sup> RT dP′/P′\n= RT ln(P/p°)'), p('The logarithm is therefore a consequence of the ideal-gas volume response. In an ideal mixture the appropriate pressure is the species partial pressure pᵢ.')),
      s('Generalize using activity', eq('aᵢ ≡ exp[(μᵢ − μᵢ°)/(RT)]'), p('For a real mixture this equation defines thermodynamic activity relative to its standard state. Ideal gases have aᵢ = pᵢ/p°; real gases use fugacity ratios. A dilute solute is often modeled by aᵢ = γᵢcᵢ/c°. The logarithmic activity form is general, but these concentration and pressure substitutions are models.'))
    ]),
    b('extent-and-finite-change', 'Why is reaction Gibbs energy a derivative?', 'Is ΔᵣG the energy change of the whole reaction?', 'index', 0, [
      s('Parameterize composition with one coordinate', p('For A ⇌ 2B, define a reaction extent ξ in moles of reaction. Then n<sub>A</sub> = n<sub>A,0</sub> − ξ and n<sub>B</sub> = n<sub>B,0</sub> + 2ξ. This is a stoichiometric coordinate, not a new conservation law.'), eq('dG = μ<sub>A</sub>(−dξ) + μ<sub>B</sub>(2dξ)\nΔᵣG = dG/dξ = 2μ<sub>B</sub> − μ<sub>A</sub>')),
      s('Follow the slope as composition changes', p('At fixed T and P the chemical potentials change as the mixture reacts. Consequently the slope ΔᵣG is not generally constant. The total Gibbs change over a finite reaction interval is:'), eq('G(ξ₂) − G(ξ₁) = ∫<sub>ξ₁</sub><sup>ξ₂</sup> ΔᵣG(ξ) dξ'), p('Replacing this integral by ΔᵣG at the initial state times the full extent would freeze the composition dependence incorrectly.')),
      s('Use the sign locally', eq('ΔᵣG &lt; 0: forward infinitesimal change lowers G\nΔᵣG &gt; 0: reverse infinitesimal change lowers G'), p('At an interior equilibrium the slope is zero. The standard slope ΔᵣG° need not be zero because the actual mixture generally has Q different from 1.'))
    ]),
    b('mixing-logarithm', 'Why does an ideal mixture use partial pressure?', 'Can we derive the mixing contribution?', 'chemical-potential', 1, [
      s('Start from an extensive mixture free energy', p('For ideal gases at a common T and total pressure P, the Gibbs energy can be written as the pure-gas reference contribution plus a mixing term. Let n = Σnᵢ and xᵢ = nᵢ/n.'), eq('G = Σ nᵢμᵢ*(T,P) + RT Σ nᵢ ln xᵢ'), p('The mixing term corresponds to ΔS<sub>mix</sub> = −RΣnᵢ ln xᵢ and zero ideal-gas enthalpy of mixing.')),
      s('Differentiate the whole mixing term', eq('Σ nᵢ ln xᵢ = Σ nᵢ ln nᵢ − n ln n\n∂/∂nⱼ = ln nⱼ + 1 − ln n − 1 = ln xⱼ'), p('Thus μⱼ = μⱼ*(T,P) + RT ln xⱼ. Combining this with the pure ideal-gas pressure term RT ln(P/p°) gives μⱼ = μⱼ° + RT ln(xⱼP/p°). Dalton’s law identifies xⱼP = pⱼ.')),
      s('State what was assumed', p('This proof assumes ideal mixing and a classical ideal-gas equation of state. Stoichiometry alone cannot determine activities in a real solution. Nonideal interactions modify the chemical potential through activity coefficients or fugacities, while ΔᵣG = Σνᵢμᵢ still holds.'))
    ])
  ],
  'equilibrium-k': [
    b('equilibrium-slope', 'Why is ΔᵣG zero at equilibrium?', 'Why set the actual reaction driving force to zero?', 'index', 0, [
      s('A minimum under material balance', p('At fixed T and P with no externally imposed useful work, a closed reacting mixture relaxes toward a constrained minimum of G. Use the reaction extent ξ to satisfy material balance automatically.'), eq('dG = ΔᵣG dξ')),
      s('Allow both directions of a small reaction', p('At an interior equilibrium a little forward reaction and a little reverse reaction are both feasible. If ΔᵣG were negative, increasing ξ would lower G. If it were positive, decreasing ξ would lower G. Only a zero first derivative can be stationary.'), eq('ΔᵣG<sub>eq</sub> = 0\n0 = ΔᵣG° + RT ln Q<sub>eq</sub>'), p('Stability additionally requires the stationary state to be a minimum. At a boundary of feasible composition, use the allowed-direction test instead.')),
      s('Use K to test another composition', eq('ΔᵣG = RT ln(Q/K)'), p('For Q &lt; K the forward reaction lowers G; for Q &gt; K the reverse reaction lowers G. At Q = K there is no net thermodynamic driving force. Molecular forward and reverse events can continue at equal rates.'))
    ]),
    b('reaction-scaling', 'Why does K depend on how the reaction is written?', 'What happens if I reverse or double the equation?', 'index', 2, [
      s('Reverse the stoichiometric coefficients', p('Replacing every νᵢ by −νᵢ reverses the reaction. The activity quotient becomes its reciprocal, and the standard reaction Gibbs energy changes sign.'), eq('Q<sub>reverse</sub> = 1/Q\nΔᵣG°<sub>reverse</sub> = −ΔᵣG°\nK<sub>reverse</sub> = 1/K')),
      s('Multiply the written reaction by a factor', p('If every coefficient is multiplied by a positive number λ, ΔᵣG° is multiplied by λ and Q becomes Q<sup>λ</sup>. Applying the exponential equilibrium relation gives:'), eq('K<sub>scaled</sub> = K<sup>λ</sup>'), p('For A ⇌ B with K = 10, writing 2A ⇌ 2B gives K = 100. The physical equilibrium composition is the same because its quotient was also squared.')),
      s('Add two independent reaction equations', p('Standard reaction Gibbs energies add when the reactions are added stoichiometrically. Exponentiating their sum makes equilibrium constants multiply.'), eq('ΔᵣG°<sub>sum</sub> = ΔᵣG°₁ + ΔᵣG°₂\nK<sub>sum</sub> = K₁K₂'), p('All constants must use the same temperature and compatible standard-state conventions.'))
    ]),
    b('standard-state', 'Why must K be dimensionless?', 'What does the standard-state symbol mean?', 'equilibrium-slope', 1, [
      s('A logarithm compares like quantities', p('The argument of a logarithm cannot carry a physical unit. Chemical potentials use activities such as pᵢ/p° or γᵢcᵢ/c°, which compare a pressure or concentration to a reference with the same units.'), eq('Q = ∏ aᵢ<sup>νᵢ</sup>,  K = Q<sub>eq</sub>')),
      s('Raw concentration products need a convention', p('For A ⇌ 2B in an ideal dilute solution, the activity quotient is ([B]/c°)²/([A]/c°) = [B]²/([A]c°). Omitting c° leaves a quantity with concentration units. Its numerical value changes if concentrations are expressed in different units.'), p('The thermodynamic K is invariant to a mere unit conversion because c° is converted too. A change of the physical standard-state convention must instead be accompanied by a consistent change in μ° and ΔᵣG°.')),
      s('Standard does not mean equilibrium', p('The superscript ° denotes reference states, not a mixture that is necessarily at equilibrium. ΔᵣG° is the stoichiometric sum of reference chemical potentials. ΔᵣG = 0 describes the actual equilibrium mixture; ΔᵣG° = 0 occurs only when the corresponding thermodynamic K is 1.'))
    ])
  ],
  'vant-hoff': [
    b('gibbs-helmholtz', 'Derive the Gibbs–Helmholtz relation', 'Why differentiate G°/T rather than G°?', 'index', 0, [
      s('Use the natural differential of G', p('For fixed composition dG = −S dT + V dP. At fixed standard pressure the temperature derivative of each standard chemical potential is minus its standard molar entropy. Summing with stoichiometric coefficients gives dΔᵣG°/dT = −ΔᵣS°.'), eq('d(ΔᵣG°/T)/dT = [T(dΔᵣG°/dT) − ΔᵣG°]/T²')),
      s('The entropy contribution cancels', eq('T(dΔᵣG°/dT) − ΔᵣG°\n= −TΔᵣS° − (ΔᵣH° − TΔᵣS°)\n= −ΔᵣH°'), p('Therefore d(ΔᵣG°/T)/dT = −ΔᵣH°/T². Differentiating G°/T is useful because equilibrium gives ΔᵣG°/T = −R ln K directly.')),
      s('No constant-enthalpy assumption yet', p('Every quantity in the cancellation is evaluated at the same temperature. ΔᵣH° and ΔᵣS° may both vary with T. Constant enthalpy is required only when replacing the later temperature integral by a simple two-temperature formula.'), p('This distinction prevents treating a narrow-range approximation as a general thermodynamic law.'))
    ]),
    b('heat-capacity-correction', 'How do heat capacities correct van ’t Hoff?', 'What if ΔᵣH° changes over the temperature range?', 'index', 3, [
      s('Use Kirchhoff’s relation', p('For the same reaction and standard phases at fixed standard pressure, define ΔᵣCₚ° = ΣνᵢCₚ,ₘ,ᵢ°. The temperature derivative of reaction enthalpy is this reaction heat-capacity difference.'), eq('dΔᵣH°/dT = ΔᵣCₚ°\nΔᵣH°(T) = ΔᵣH°(T₁) + ΔᵣCₚ°(T − T₁)'), p('The second line assumes ΔᵣCₚ° is constant over the interval, a less restrictive approximation than constant ΔᵣH°.')),
      s('Integrate the differential equation', eq('ln(K₂/K₁) = [ΔᵣH°(T₁)/R](1/T₁ − 1/T₂)\n+ (ΔᵣCₚ°/R)[ln(T₂/T₁) + T₁/T₂ − 1]'), p('This follows by integrating [ΔᵣH°(T₁) + ΔᵣCₚ°(T − T₁)]/(RT²). Setting ΔᵣCₚ° = 0 recovers the usual formula. The bracket multiplying ΔᵣCₚ° vanishes at T₂ = T₁.')),
      s('Watch for a change of physical model', p('A phase transition in a standard-state species can introduce a discontinuity in entropy or enthalpy derivatives. Integrate piecewise with the appropriate phases and transition data. Extrapolating one constant heat-capacity model through such a transition is not justified.'))
    ]),
    b('equilibrium-not-rate', 'Why does heating change K without specifying the rate?', 'Does a larger K mean a faster reaction?', 'gibbs-helmholtz', 2, [
      s('Equilibrium is an endpoint statement', eq('d ln K/dT = ΔᵣH°/(RT²)'), p('An endothermic written reaction has ΔᵣH° &gt; 0, so K increases with T. This changes the equilibrium activity ratio. It does not state how quickly the mixture approaches that ratio.')),
      s('A simple kinetic model makes the distinction visible', p('For an elementary reversible first-order ideal-dilute model A ⇌ B, equilibrium requires k<sub>f</sub>[A] = k<sub>r</sub>[B], so K = k<sub>f</sub>/k<sub>r</sub> with compatible activity conventions. Both rate constants may increase with temperature, yet their ratio can either increase or decrease.'), eq('ln K = ln k<sub>f</sub> − ln k<sub>r</sub>'), p('A catalyst can increase both rates while preserving their equilibrium ratio. It changes the time scale, not the thermodynamic equilibrium constant.')),
      s('Check the sign numerically', p('For approximately constant ΔᵣH° = +40.0 kJ mol⁻¹ between 300 K and 310 K, ln(K₂/K₁) = (40000/8.314)(1/300 − 1/310) ≈ 0.517. Hence K₂/K₁ ≈ 1.68. No activation energy was needed for this equilibrium prediction.'))
    ])
  ],
  'first-order': [
    b('constant-hazard', 'Why does first-order decay give an exponential?', 'What physical model gives −dc/dt = kc?', 'index', 0, [
      s('Assume a constant probability per surviving molecule', p('Suppose each surviving A has probability k dt + o(dt) of disappearing during a short interval dt, independent of its age and of the number of other A molecules. This constant-hazard assumption is a model for unimolecular decay, not a consequence of stoichiometry.'), eq('N(t + dt) − N(t) = −kN(t) dt\ndN/dt = −kN')),
      s('Convert molecule count into concentration', p('At fixed volume, c = N/(N<sub>A</sub>V), so c obeys the same equation. The survival probability f(t) obeys df/dt = −kf with f(0) = 1, giving f(t) = e<sup>−kt</sup>.'), eq('f(t + s) = f(t)f(s)'), p('This multiplicative property means that equal time intervals remove equal fractions of what remains, rather than equal absolute amounts.')),
      s('An observed first-order law need not be elementary', p('A bimolecular rate k₂[A][B] behaves approximately as k<sub>obs</sub>[A] if B is in such large excess that [B] barely changes; k<sub>obs</sub> = k₂[B]<sub>excess</sub>. This is pseudo-first-order kinetics. The exponential holds only while that approximation and the temperature remain adequate.'))
    ]),
    b('diagnosing-first-order', 'How do data test a first-order model?', 'What does a straight logarithmic plot establish?', 'index', 2, [
      s('Linearize a dimensionless ratio', eq('ln(c/c₀) = −kt'), p('A plot against t has slope −k and intercept zero when the chosen t = 0 and c₀ are exact. Taking ln c without a reference concentration is shorthand; an actual logarithm requires a dimensionless argument.')),
      s('Prefer the original observable for fitting', p('A logarithmic plot is a useful diagnostic, but transforming noisy measurements changes the error distribution. When concentration errors are approximately additive, fit c(t) = c₀e<sup>−kt</sup> to the original values and inspect residuals. Persistent curvature or an offset can indicate a competing source, a background signal, or a changing rate constant.')),
      s('Half-life and variable k', eq('constant k: t½ = ln 2/k\nvariable k: ln(c/c₀) = −∫<sub>0</sub><sup>t</sup> k(t′) dt′'), p('If temperature changes, the exponential with one constant k generally fails. A half-life then satisfies ∫k(t′)dt′ = ln 2 over the relevant interval, and successive halves need not take the same time.'))
    ]),
    b('changing-volume', 'What if the reacting volume changes?', 'Why insist on fixed volume?', 'constant-hazard', 1, [
      s('Differentiate the amount balance', p('Let n<sub>A</sub> = cV and suppose molecular disappearance remains first order in the amount, with dn<sub>A</sub>/dt = −kn<sub>A</sub>. A moving boundary changes concentration even without changing molecule number.'), eq('V dc/dt + c dV/dt = −kcV\ndc/dt = −kc − (c/V)dV/dt')),
      s('Integrate using the known volume history', eq('c(t)/c₀ = [V₀/V(t)] e<sup>−kt</sup>'), p('The exponential describes chemical survival. The volume ratio separately describes dilution or compression. For k = 0 and a doubling of volume, concentration halves even though no molecules react.')),
      s('Specify which half-life you mean', p('The amount half-life remains ln 2/k under this amount-based model. The time for concentration to halve can differ because volume also changes. In a flow reactor, inflow and outflow add further terms; the closed-batch derivation cannot be transferred without a new balance.'))
    ])
  ],
  'second-order': [
    b('rate-conventions', 'Where do factors of two enter a second-order law?', 'What exactly does k measure?', 'index', 0, [
      s('Separate event rate from species disappearance', p('For 2A → products, one reaction event consumes two A molecules. The rate of reaction per volume is conventionally r = −(1/2)dc/dt. If a kinetic model gives r = k<sub>r</sub>c², the measured disappearance law is:'), eq('−dc/dt = 2k<sub>r</sub>c² ≡ k<sub>d</sub>c²')),
      s('Integrate the law actually stated', eq('1/c(t) = 1/c₀ + k<sub>d</sub>t\nt½ = 1/(k<sub>d</sub>c₀) = 1/(2k<sub>r</sub>c₀)'), p('The workbook defines k directly by disappearance, so its formula contains no extra 2. Either convention is acceptable if the definition of k is carried through every equation.')),
      s('Why a quadratic dependence can arise', p('In an elementary well-mixed binary encounter model the number of possible A–A pairs scales as N(N − 1)/2. At large N and fixed density, the reaction-event rate per volume scales as c². The pair-count factor and event stoichiometry are absorbed into the stated rate constant. An overall balanced equation alone does not establish this model.'))
    ]),
    b('two-reactants', 'Why does k[A][B] require another formula?', 'Is every second-order integrated law the same?', 'index', 2, [
      s('Use stoichiometry to keep one independent variable', p('For A + B → products at fixed volume, let initial concentrations be a and b and let x be the reacted concentration. Then [A] = a − x, [B] = b − x, and dx/dt = k(a − x)(b − x).')),
      s('Integrate for unequal initial concentrations', eq('1/[(a − x)(b − x)]\n= [1/(a − x) − 1/(b − x)]/(b − a)\nkt = [1/(b − a)] ln{a(b − x)/[b(a − x)]}'), p('The logarithm compares dimensionless ratios. This formula is valid for a ≠ b while both reactant concentrations remain positive. Substituting x = 0 gives zero elapsed time.')),
      s('Recover the familiar special cases', p('If a = b, the concentrations remain equal and the law becomes −d[A]/dt = k[A]², giving the reciprocal formula. If b is much larger than a and barely depleted, the approximate law is first order in A with k<sub>obs</sub> = kb.'), p('Reaction order specifies the total concentration power; it does not uniquely specify the integral when multiple concentrations vary.'))
    ]),
    b('successive-halves', 'Why do successive half-lives get longer?', 'Can we see the slowing directly?', 'rate-conventions', 1, [
      s('Solve explicitly for concentration', eq('c(t) = c₀/(1 + kc₀t)'), p('At the first half-life τ = 1/(kc₀), concentration is c₀/2. To reach c₀/4, the total elapsed time is 3τ. The second halving interval is therefore 2τ, not τ.')),
      s('Generalize to repeated halvings', eq('c(tₘ) = c₀/2<sup>m</sup>\ntₘ = (2<sup>m</sup> − 1)/(kc₀)\ntₘ − tₘ₋₁ = 2<sup>m−1</sup>/(kc₀)'), p('Each new halving begins at half the previous concentration, so the next interval doubles. The decreasing encounter frequency is reflected in the algebra.')),
      s('Compare fractional disappearance rates', eq('−(1/c) dc/dt = kc  (second order)\n−(1/c) dc/dt = k  (first order)'), p('For second order, even the fraction disappearing per second falls as c falls. With k = 0.50 L mol⁻¹ s⁻¹ and c₀ = 0.20 mol L⁻¹, the first three halving intervals are 10 s, 20 s, and 40 s.'))
    ])
  ],
  buffer: [
    b('activities-and-ph', 'Why use activities in the buffer equation?', 'Is pH simply minus log concentration?', 'index', 0, [
      s('Start with a thermodynamic equilibrium constant', p('For HA ⇌ H⁺ + A⁻, take solvent water into the acid standard-state convention. At equilibrium the thermodynamic constant is Kₐ = a<sub>H⁺</sub>a<sub>A⁻</sub>/a<sub>HA</sub>. Every activity is dimensionless.'), eq('pH = −log₁₀ a<sub>H⁺</sub>\npH = pKₐ + log₁₀(a<sub>A⁻</sub>/a<sub>HA</sub>)')),
      s('Expose the concentration approximation', eq('aᵢ = γᵢcᵢ/c°\npH = pKₐ + log₁₀(c<sub>A⁻</sub>/c<sub>HA</sub>)\n+ log₁₀(γ<sub>A⁻</sub>/γ<sub>HA</sub>)'), p('The standard concentration cancels in the acid/base ratio. The activity-coefficient ratio must be close to 1 before the usual concentration formula follows. Ionic strength can make this correction significant.')),
      s('Keep two approximations distinct', p('Approximating activities by equilibrium concentrations is one step. Replacing equilibrium concentrations by prepared amounts is a second step. Neither follows merely from taking logarithms. A buffer can be concentrated enough to minimize dissociation changes yet nonideal enough to require activity corrections.'))
    ]),
    b('neutralization-bookkeeping', 'How should added strong acid or base be handled?', 'Can I use the original mixing amounts?', 'index', 3, [
      s('Do stoichiometry before equilibrium', p('Assume an initial buffer contains 0.100 mol HA and 0.100 mol A⁻. Adding 0.0200 mol strong acid first converts A⁻ into HA. The prepared amounts after neutralization are 0.0800 mol A⁻ and 0.120 mol HA.'), eq('A⁻ + H⁺ → HA\npH ≈ pKₐ + log₁₀(0.0800/0.120)\n= pKₐ − 0.176'), p('The common final volume cancels in this concentration ratio. Any dilution still affects buffer capacity and the size of subsequent equilibrium shifts.')),
      s('Then check the buffer approximation', p('Using these amounts assumes the later weak-acid dissociation changes them by only a small fraction and activity effects are adequate. If the strong acid consumes all A⁻, the logarithmic expression with a zero denominator or numerator is not a physical solution. Solve the remaining acid/base equilibrium and any excess strong acid instead.')),
      s('The same ratio can hide very different resilience', p('Two buffers can have the same acid/base ratio and pH while containing different total amounts. The more concentrated buffer can absorb more added acid before that ratio changes appreciably. pH is a state descriptor, whereas resistance to a perturbation requires additional concentration information.'))
    ]),
    b('buffer-capacity', 'Derive the buffer capacity', 'Why does an equal acid/base mixture resist pH change best?', 'activities-and-ph', 2, [
      s('Use an ideal dilute monoprotic model', p('Let C = [HA] + [A⁻] be the fixed analytical buffer concentration, h = [H⁺], and κ = Kₐc°. Neglect dilution during titration and hold activity coefficients constant. Acid equilibrium gives the deprotonated fraction f = κ/(κ + h).')),
      s('Differentiate the amount of bound base', p('A small amount of strong base raises the deprotonated concentration Cf. Since dh/dpH = −(ln 10)h in this ideal model, its buffer contribution per pH unit is:'), eq('β<sub>buffer</sub> = C df/dpH\n= (ln 10) Cκh/(κ + h)²'), p('β has concentration units per pH unit. The factor κh/(κ + h)² is largest at h = κ, corresponding to pH = pKₐ and equal HA and A⁻ concentrations.')),
      s('Include the solvent when necessary', eq('β<sub>total</sub> = (ln 10)[Cκh/(κ + h)² + h + K<sub>w</sub>(c°)²/h]'), p('The last terms represent free hydrogen and hydroxide ions. The buffer-only maximum is (ln 10)C/4. Doubling C doubles this contribution without changing the pH of an equal-ratio mixture, within the stated ideal model.'))
    ])
  ],
  'weak-acid': [
    b('balances', 'Where does the weak-acid quadratic come from?', 'What equations determine all the concentrations?', 'index', 1, [
      s('Write independent constraints', p('For a solution prepared from pure monoprotic HA with no added ions, mass balance gives [HA] + [A⁻] = c₀. Electrical neutrality gives [H⁺] = [A⁻] + [OH⁻]. In the ideal dilute model acid equilibrium and water equilibrium complete the system.'), eq('Kₐ = [H⁺][A⁻]/(c°[HA])\nK<sub>w</sub> = [H⁺][OH⁻]/(c°)²')),
      s('Neglect water as an explicit model reduction', p('If [OH⁻] is negligible relative to [H⁺], set h = [H⁺] ≈ [A⁻] = x. Then [HA] = c₀ − x and the acid equation becomes:'), eq('x² = κ(c₀ − x),  κ = Kₐc°\nx = [−κ + √(κ² + 4κc₀)]/2'), p('The other quadratic root is negative and cannot represent a concentration. The positive root automatically satisfies 0 &lt; x &lt; c₀.')),
      s('Use a numerically stable equivalent root', eq('x = 2κc₀/[κ + √(κ² + 4κc₀)]'), p('Rationalizing avoids subtracting two nearly equal positive numbers when c₀/κ is tiny. This algebraic improvement does not repair a physical failure of the negligible-water approximation.'))
    ]),
    b('approximation-checks', 'How small must dissociation be?', 'Does a small Kₐ guarantee the square-root formula?', 'index', 3, [
      s('Use a dimensionless expansion parameter', p('Set y = x/c₀ and ε = κ/c₀. The quadratic becomes y² = ε(1 − y). Small dissociation means y ≪ 1, so y ≈ √ε. It depends on κ/c₀, not on Kₐ alone.'), eq('x ≈ √(κc₀)\nx/c₀ ≈ √(κ/c₀)')),
      s('Quantify the error rather than naming a rule', p('If the true dissociation fraction is y, the square-root estimate divided by the quadratic value is 1/√(1 − y). At y = 0.05 the concentration overestimate is about 2.60%. The common 5% dissociation rule is therefore a tolerance choice, not a thermodynamic threshold.'), eq('x<sub>approx</sub>/x<sub>quadratic</sub> = (1 − y)<sup>−1/2</sup>')),
      s('Check water independently', p('Require the predicted hydrogen concentration to be much greater than √K<sub>w</sub>c°. A weak acid can be so dilute that water controls the pH even if a small-dissociation check appears harmless. For Kₐ = 10⁻⁵, c₀ = 0.100 mol L⁻¹, and c° = 1 mol L⁻¹, the square-root estimate is 0.00100 mol L⁻¹, whereas the quadratic gives about 0.000995 mol L⁻¹.'))
    ]),
    b('water-autoionization', 'What equation includes water autoionization?', 'Why can an extremely dilute acid not give alkaline pH?', 'balances', 1, [
      s('Retain charge balance exactly within the ideal model', p('Let h = [H⁺], κ = Kₐc°, and W = K<sub>w</sub>(c°)². Water gives [OH⁻] = W/h. Acid equilibrium and mass balance give [A⁻] = κc₀/(h + κ).'), eq('h = κc₀/(h + κ) + W/h')),
      s('Obtain a single polynomial', eq('h³ + κh² − (κc₀ + W)h − κW = 0'), p('The original charge-balance equation is often more convenient to solve numerically than the cubic. For h &gt; 0 its left-minus-right derivative is 1 + κc₀/(h + κ)² + W/h², which is positive. There is therefore a unique positive physical root.')),
      s('Take the infinite-dilution limit', p('As c₀ tends to zero, the charge balance tends to h = W/h, giving h = √W = √K<sub>w</sub>c°. The pH approaches neutral water at the specified temperature. A pure acid solution in this model has h greater than √W, so it cannot become alkaline simply because its analytical acid concentration is small.'), p('Neutral pH is pK<sub>w</sub>/2; the number 7 applies only when pK<sub>w</sub> is approximately 14.'))
    ])
  ],
  nernst: [
    b('electrical-work', 'Why is ΔᵣG = −nFE?', 'How does cell voltage measure chemical free energy?', 'index', 0, [
      s('Convert reaction extent into charge', p('Let the balanced cell reaction transfer n electrons per formula reaction, with extent ξ measured in moles of reaction. The magnitude of charge delivered through the external circuit is dq<sub>charge</sub> = nF dξ. Here n is a stoichiometric number, not the amount of gas used in PV = nRT.'), eq('δw<sub>electrical,out</sub> = E dq<sub>charge</sub> = nFE dξ')),
      s('Use the reversible useful-work theorem', p('At fixed T and P, the maximum non-PV work output is −dG. A reversible cell reaches that limit; electrical work on the cell is the negative of its output.'), eq('dG = δw<sub>electrical,on,rev</sub> = −nFE dξ\nΔᵣG = (∂G/∂ξ)<sub>T,P</sub> = −nFE'), p('The units are (mol electrons/mol reaction)(C/mol electrons)(J/C) = J/mol reaction. A positive reversible E corresponds to a negative forward reaction driving force.')),
      s('A loaded voltage can be different', p('A finite current produces resistance losses, electrode overpotentials, and concentration gradients. The measured terminal voltage then differs from the reversible E used in the Nernst equation. Inferring equilibrium chemical free energy from a loaded voltage requires accounting for those irreversible effects.'))
    ]),
    b('reaction-quotient', 'How do I construct Q and handle the signs?', 'Which concentrations belong in a cell equation?', 'index', 1, [
      s('Balance the written cell reaction first', p('For Zn(s) + Cu²⁺(aq) → Zn²⁺(aq) + Cu(s), n = 2. Pure solid activities are approximately 1 in their usual standard states, so the activity quotient and reversible potential are:'), eq('Q = a<sub>Zn²⁺</sub>/a<sub>Cu²⁺</sub>\nE = E° − (RT/2F) ln Q'), p('At 298.15 K, Q = 100 lowers E by 0.05916 V. The denominator is 2 because the balanced reaction transfers two electrons.')),
      s('Reversing and scaling are different operations', p('Reversing the reaction sends Q to 1/Q, ΔᵣG° to −ΔᵣG°, and E° to −E°. The electron-transfer magnitude n stays positive. Multiplying the entire reaction by λ sends Q to Q<sup>λ</sup> and n to λn, leaving E unchanged.'), eq('(RT/(λnF)) ln(Q<sup>λ</sup>) = (RT/nF) ln Q'), p('Voltage is intensive. Reaction energy and transferred charge scale together.')),
      s('At equilibrium the actual voltage vanishes', eq('Q = K,  E = 0\nE° = (RT/nF) ln K'), p('A nonzero E° is compatible with E = 0 because equilibrium generally occurs at Q different from 1. The 0.05916 V decimal-log coefficient is specific to 298.15 K.'))
    ]),
    b('work-bound', 'Why does reversibility maximize electrical output?', 'Where does dissipated free energy go?', 'electrical-work', 1, [
      s('Keep entropy production in the energy balance', p('For a closed cell at fixed T and P exchanging heat with a reservoir at T, include electrical work on the cell. Energy and entropy balances give:'), eq('ΔG = w<sub>electrical,on</sub> − T S<sub>gen</sub>\nw<sub>electrical,out</sub> = −ΔG − T S<sub>gen</sub>'), p('Assume the stated thermal and mechanical surroundings account for all entropy changes. The entropy generated is nonnegative.')),
      s('Identify the lost useful work', eq('lost electrical work = T S<sub>gen</sub> ≥ 0'), p('In the reversible limit S<sub>gen</sub> = 0 and all of −ΔG can become electrical work. At finite current, some available work is dissipated and eventually appears as additional heat in the surroundings. Energy is conserved even when useful work is lost.')),
      s('Apply the statement locally during discharge', p('As composition changes, E and ΔᵣG both change. Reversible work over a finite discharge is ∫nFE(ξ)dξ = −∫ΔᵣG(ξ)dξ, not generally one initial voltage times the whole charge. The Nernst equation supplies the local reversible potential at each composition.'))
    ])
  ]
};
